fn fibonacci(n: Int) -> Int {
    if n == 1 {
        return 1
    }
    if n == 2 {
        return 1
    }
    fibonacci(n - 1) + fibonacci(n - 2)
}

fn main() {
    print(fibonacci(20))
}

fn fib(n: Int) -> Int {
    if n == 1 {
        return 1
    }
    if n == 2 {
        return 1
    }
    return fib(n - 1) + fib(n - 2)
}

fn main() {
    print(fib(20))
