use std::f64::consts;

fn area(r: &Rect) -> f64 {
    r.w * r.h
}

fn area(t: &Tri) -> f64 {
    0.5 * t.a * t.b
}

fn area(r: &Rec2) -> f64 {
    r.w * r.h
}

fn perimeter(r: &Rect) -> f64 {
    2 * (r.w + r.h)
}

fn perimeter(t: &Tri) -> f64 {
    t.a + t.b + t.c
}

fn perimeter(r: &Rec2) -> f64 {
    2 * (r.w + r.h)
}

